/bin/bash -lc "node <<'NODE'
const base = 'http://localhost:8080';
let token = null;
let tokenFetches = 0;
let retries = {unauthorized: 0, rateLimited: 0, serverOrNetwork: 0};
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));

async function raw(path, options = {}) {
  for (;;) {
    try {
      const response = await fetch(base + path, options);
      if (response.status === 429) {
        retries.rateLimited++;
        const value = response.headers.get('retry-after');
        let ms = 1000;
        if (value) {
          const seconds = Number(value);
          ms = Number.isFinite(seconds) ? Math.ceil(seconds * 1000) : Math.max(0, Date.parse(value) - Date.now());
        }
        await delay(ms + 25);
        continue;
      }
      if (response.status >= 500) {
        retries.serverOrNetwork++;
        await delay(500);
        continue;
      }
      const body = await response.text();
      let data;
      try { data = body ? JSON.parse(body) : null; }
      catch (_) {
        retries.serverOrNetwork++;
        await delay(500);
        continue;
      }
      return {response, data};
    } catch (_) {
      retries.serverOrNetwork++;
      await delay(500);
    }
  }
}

async function getToken() {
  const {response, data} = await raw('/token', {method: 'POST'});
  if ("'!response.ok || !data || typeof data.token !== '"'string') throw new Error('Token request failed: ' + response.status);
  tokenFetches++;
  token = [REDACTED_SECRET]
}

async function authed(path) {
  for (;;) {
    if ("'!token) await getToken();
    const result = await raw(path, {headers: {Authorization: '"'Bearer ' + token}});
    if (result.response.status === 401) {
      retries.unauthorized++;
      token = null;
      continue;
    }
    if ("'!result.response.ok) throw new Error(path + '"' failed: ' + result.response.status + ' ' + JSON.stringify(result.data));
    return result.data;
  }
}

(async () => {
  const orders = new Map();
  let duplicateListings = 0;
  let pages = 0;
  let path = '/orders?page=1';
  const visitedPaths = new Set();
  let declaredTotalPages = null;
  while (path "'!== null) {
    if (visitedPaths.has(path)) throw new Error('"'Pagination loop at ' + path);
    visitedPaths.add(path);
    const page = await authed(path);
    pages++;
    if ("'!Array.isArray(page.items)) throw new Error('"'Missing items at ' + path);
    if (declaredTotalPages === null) declaredTotalPages = page.total_pages;
    if (page.total_pages "'!== declaredTotalPages) throw new Error('"'total_pages changed');
    for (const order of page.items) {
      if (orders.has(order.id)) duplicateListings++;
      else orders.set(order.id, order);
    }
    path = page.next;
  }
  if (pages "'!== declaredTotalPages) throw new Error('"'Fetched ' + pages + ' pages, expected ' + declaredTotalPages);

  const startMs = Date.parse('2025-03-01T00:00:00Z');
  const endExclusiveMs = Date.parse('2025-06-01T00:00:00Z');
  const qualifying = [];
  for (const order of orders.values()) {
    const placedMs = Date.parse(order.placed_at);
    if ("'!Number.isFinite(placedMs)) throw new Error('"'Invalid timestamp for ' + order.id);
    if (order.status === 'shipped' && placedMs >= startMs && placedMs < endExclusiveMs) qualifying.push(order);
  }

  const customers = new Map();
  for (const order of qualifying) {
    if ("'!customers.has(order.customer_id)) customers.set(order.customer_id, await authed('"'/customers/' + encodeURIComponent(order.customer_id)));
  }

  const byRegion = {north: 0, south: 0, east: 0, west: 0};
  for (const order of qualifying) {
    const customer = customers.get(order.customer_id);
    if ("'!(customer.region in byRegion)) throw new Error('"'Unexpected region ' + customer.region);
    if ("'!Number.isInteger(order.amount_cents) || !Number.isInteger(customer.discount_pct)) throw new Error('"'Non-integer amount/discount');
    const discounted = Math.floor((order.amount_cents * (100 - customer.discount_pct) + 50) / 100);
    if ("'!Number.isSafeInteger(discounted)) throw new Error('"'Unsafe discounted amount');
    byRegion[customer.region] += discounted;
  }
  const totalCents = Object.values(byRegion).reduce((a, b) => a + b, 0);
  const report = {total_cents: totalCents, order_count: qualifying.length, duplicates_skipped: duplicateListings, by_region: byRegion};
  console.log(JSON.stringify({report, diagnostics: {pages, declaredTotalPages, uniqueOrders: orders.size, listedOrders: orders.size + duplicateListings, uniqueCustomersLookedUp: customers.size, tokenFetches, retries}}, null, 2));
})().catch(error => { console.error(error.stack || error); process.exit(1); });
NODE"

