/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const path = '/workspace/result.json';
const data = JSON.parse(fs.readFileSync(path, 'utf8'));
const top = Object.keys(data);
const regions = Object.keys(data.by_region);
const expectedTop = ['total_cents', 'order_count', 'duplicates_skipped', 'by_region'];
const expectedRegions = ['north', 'south', 'east', 'west'];
if (JSON.stringify(top) "'!== JSON.stringify(expectedTop)) throw new Error('"'Wrong top-level keys/order: ' + top);
if (JSON.stringify(regions) "'!== JSON.stringify(expectedRegions)) throw new Error('"'Wrong region keys/order: ' + regions);
for (const value of [data.total_cents, data.order_count, data.duplicates_skipped, ...Object.values(data.by_region)]) {
  if ("'!Number.isInteger(value)) throw new Error('"'Non-integer output');
}
const regionSum = Object.values(data.by_region).reduce((a, b) => a + b, 0);
if (regionSum "'!== data.total_cents) throw new Error('"'Region sum mismatch');
console.log(JSON.stringify({valid_json: true, exact_keys: true, region_sum: regionSum, matches_total: true, path}, null, 2));
NODE"

